CREATE TABLE users (id BIGSERIAL PRIMARY KEY, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('SALESMAN','ADMIN','PRODUCTION','AUDITOR','OWNER')));
CREATE TABLE items (id BIGSERIAL PRIMARY KEY, sku TEXT NOT NULL UNIQUE, name TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('RAW','PACKAGING','FINISHED')), unit TEXT NOT NULL, price NUMERIC(14,4) NOT NULL DEFAULT 0, selling_price NUMERIC(14,2), gst_rate NUMERIC(5,2) NOT NULL DEFAULT 0);
CREATE TABLE customers (id BIGSERIAL PRIMARY KEY, name TEXT NOT NULL UNIQUE, state_code CHAR(2) NOT NULL);
CREATE TABLE bom (id BIGSERIAL PRIMARY KEY, finished_item_id BIGINT NOT NULL REFERENCES items(id), expected_output NUMERIC(18,4) NOT NULL CHECK(expected_output>0), version INT NOT NULL DEFAULT 1, UNIQUE(finished_item_id,version));
CREATE TABLE bom_lines (bom_id BIGINT REFERENCES bom(id), item_id BIGINT REFERENCES items(id), planned_qty NUMERIC(18,4) NOT NULL CHECK(planned_qty>=0), PRIMARY KEY(bom_id,item_id));
CREATE TABLE stock_movements (id BIGSERIAL PRIMARY KEY, item_id BIGINT NOT NULL REFERENCES items(id), delta NUMERIC(18,4) NOT NULL CHECK(delta<>0), source_type TEXT NOT NULL CHECK(source_type IN ('OPENING','PURCHASE','PRODUCTION_ISSUE','PRODUCTION_OUTPUT','DISPATCH')), source_id BIGINT NOT NULL, line_key TEXT NOT NULL, unit_cost NUMERIC(18,6), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(source_type,source_id,line_key));
CREATE INDEX stock_movements_item_idx ON stock_movements(item_id,id);
CREATE VIEW stock_balances AS SELECT i.id item_id,i.sku,i.name,i.unit,COALESCE(SUM(m.delta),0) quantity FROM items i LEFT JOIN stock_movements m ON m.item_id=i.id GROUP BY i.id;
CREATE TABLE purchases (id BIGSERIAL PRIMARY KEY, reference TEXT NOT NULL UNIQUE, item_id BIGINT NOT NULL REFERENCES items(id), qty NUMERIC(18,4) NOT NULL CHECK(qty>0), unit_cost NUMERIC(18,6) NOT NULL CHECK(unit_cost>=0), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE production_runs (id BIGSERIAL PRIMARY KEY, request_key UUID NOT NULL UNIQUE, bom_id BIGINT NOT NULL REFERENCES bom(id), good_output NUMERIC(18,4) NOT NULL CHECK(good_output>0), expected_output NUMERIC(18,4) NOT NULL, material_cost NUMERIC(18,2) NOT NULL, overhead NUMERIC(18,2) NOT NULL, cost_per_packet NUMERIC(18,2) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE production_issues (run_id BIGINT REFERENCES production_runs(id), item_id BIGINT REFERENCES items(id), qty NUMERIC(18,4) NOT NULL CHECK(qty>0), damaged_qty NUMERIC(18,4) NOT NULL DEFAULT 0, planned_qty NUMERIC(18,4) NOT NULL, variance_pct NUMERIC(12,2), PRIMARY KEY(run_id,item_id));
CREATE TABLE orders (id BIGSERIAL PRIMARY KEY, request_key UUID NOT NULL UNIQUE, customer_id BIGINT NOT NULL REFERENCES customers(id), salesman_id BIGINT NOT NULL REFERENCES users(id), item_id BIGINT NOT NULL REFERENCES items(id), qty NUMERIC(18,4) NOT NULL CHECK(qty>0), status TEXT NOT NULL DEFAULT 'SUBMITTED' CHECK(status IN ('SUBMITTED','APPROVED','INVOICED','DISPATCHED','REJECTED')), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE invoices (id BIGSERIAL PRIMARY KEY, order_id BIGINT NOT NULL UNIQUE REFERENCES orders(id), invoice_no TEXT NOT NULL UNIQUE, taxable NUMERIC(18,2) NOT NULL, cgst NUMERIC(18,2) NOT NULL, sgst NUMERIC(18,2) NOT NULL, igst NUMERIC(18,2) NOT NULL, total NUMERIC(18,2) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE dispatches (id BIGSERIAL PRIMARY KEY, invoice_id BIGINT NOT NULL UNIQUE REFERENCES invoices(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE payments (id BIGSERIAL PRIMARY KEY, invoice_id BIGINT NOT NULL REFERENCES invoices(id), reference TEXT NOT NULL UNIQUE, amount NUMERIC(18,2) NOT NULL CHECK(amount>0), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE audit_events (id BIGSERIAL PRIMARY KEY, actor_id BIGINT REFERENCES users(id), entity_type TEXT NOT NULL, entity_id BIGINT NOT NULL, action TEXT NOT NULL, details JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE inventory_mutex (id INT PRIMARY KEY CHECK(id=1));
